 "content": "def transform(grid):
    """Highlight missing foreground cells in the shorter aligned panel."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate horizontal bands of non-background cells.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    occupied = [any(v != bg for v in row) for row in grid]
    bands = []
    i = 0
    while i < h:
        if not occupied[i]:
            i += 1
            continue
        j = i
        while j < h and occupied[j]:
            j += 1
        bands.append((i, j))
        i = j
    if len(bands) < 2:
        return out
    # Use the pair of similarly sized panels, typically the first and last bands.
    a, b = bands[0], bands[-1]
    n = min(a[1] - a[0], b[1] - b[0])
    if n <= 0:
        return out
    # Compare aligned rows. The shorter panel is the incomplete one; the
