    """Continue the shorter of two aligned horizontal patterns with 1s."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    if not h or not w:
        return out

    # The most frequent value is the canvas/background color; all other
    # colors form the drawn pattern (including negative/knockout patterns).
    frequencies = {}
    for row in grid:
        for value in row:
            frequencies[value] = frequencies.get(value, 0) + 1
    background = max(frequencies, key=frequencies.get)

    # Find horizontally occupied row-bands, separated by fully blank rows.
    bands = []
    r = 0
    while r < h:
        if all(value == background for value in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(value != background for value in grid[r]):
            r += 1
        bands.append((start, r))

    if len(bands) < 2:
        return out

    first, second = bands[0], bands[-1]
    row_count = min(first[1] - first[0], second[1] - second[0])
    for offset in range(row_count):
        r1, r2 = first[0] + offset, second[0] + offset
        end1 = max((c for c, value in enumerate(grid[r1]) if value != background), default=-1)
        end2 = max((c for c, value in enumerate(grid[r2]) if value != background), default=-1)
        if end1 == end2:
            continue
        if end1 < end2:
            target, source, start_col = r1, r2, end1 + 1
        else:
            target, source, start_col = r2, r1, end2 + 1
        for c in range(start_col, w):
            if grid[source][c] != background and grid[target][c] == background:
